display.text:
    /// Changes the permissions on the underlying file.
    ///
    /// # Platform-specific behavior
    ///
    /// This function currently corresponds to the `fchmod` function on Unix and
    /// the `SetFileInformationByHandle` function on Windows. Note that, this
    /// [may change in the future][changes].
    ///
    /// [changes]: https://doc.rust-lang.org/std/io/index.html#platform-specific-behavior
    ///
    /// # Errors
    ///
    /// This function will return an error if the user lacks permission change
    /// attributes on the underlying file. It may also return an error in other
    /// os-specific unspecified cases.
    ///
    /// # Examples
    ///
    /// ```no_run
    /// use tokio::fs::File;
    ///
    /// # async fn dox() -> std::io::Result<()> {
    /// let file = File::open("foo.txt").await?;
    /// let mut perms = file.metadata().await?.permissions();
    /// perms.set_readonly(true);
    /// file.set_permissions(perms).await?;
    /// # Ok(())
    /// # }
    /// ```
    pub async fn set_permissions(&self, perm: Permissions) -> io::Result<()> {
        let std = self.std.clone();
        asyncify(move || std.set_permissions(perm)).await
    }

    /// Set the maximum buffer size for the underlying [`AsyncRead`] / [`AsyncWrite`] operation.
    ///
    /// Although Tokio uses a sensible default value for this buffer size, this function would be
    /// useful for changing that default depending on the situation.
    ///
    /// # Examples
    ///
    /// ```no_run
    /// use tokio::fs::File;
    /// use tokio::io::AsyncWriteExt;
    ///
    /// # async fn dox() -> std::io::Result<()> {
    /// let mut file = File::open("foo.txt").await?;
    ///
    /// // Set maximum buffer size to 8 MiB
    /// file.set_max_buf_size(8 * 1024 * 1024);
    ///
    /// let mut buf = vec![1; 1024 * 1024 * 1024];
    ///
    /// // Write the 1 GiB buffer in chunks up to 8 MiB each.
    /// file.write_all(&mut buf).await?;
    /// # Ok(())
    /// # }
    /// ```
    pub fn set_max_buf_size(&mut self, max_buf_size: usize) {
        self.max_buf_size = max_buf_size;
    }
}

impl AsyncRead for File {
    fn poll_read(
        self: Pin<&mut Self>,
        cx: &mut Context<'_>,
        dst: &mut ReadBuf<'_>,
    ) -> Poll<io::Result<()>> {
        ready!(crate::trace::trace_leaf(cx));
        let me = self.get_mut();
        let inner = unsafe { &mut *me.inner.c.get() };

        loop {
            match inner.state {
                State::Idle(ref mut buf_cell) => {
                    let mut buf = buf_cell.take().unwrap();

                    if !buf.is_empty() {
                        buf.copy_to(dst);
                        *buf_cell = Some(buf);
                        return Poll::Ready(Ok(()));
                    }

                    let std = me.std.clone();
                    let dst_remaining = dst.buf.len() - dst.filled;
                    let max_buf_size = cmp::min(dst_remaining, me.max_buf_size);
                    inner.state = State::Busy(spawn_blocking(move || {
                        let unread = buf.buf.len() - buf.pos;
                        assert_eq!(unread, 0);
                        buf.buf.reserve(max_buf_size);
                        let spare = &mut buf.buf.spare_capacity_mut()[..max_buf_size];
                        let raw = unsafe { &mut *(spare as *mut [MaybeUninit<u8>] as *mut [u8]) };
                        let res = loop {
                            match Read::read(&mut &*std, raw) {
                                Err(ref e) if e.kind() == io::ErrorKind::Interrupted => {}
                                other => break other,
                            }
                        };
                        if let Ok(n) = res {
                            unsafe { buf.buf.set_len(n) }
                        } else {
                            buf.buf.clear();
                        }
                        assert_eq!(buf.pos, 0);
                        (Operation::Read(res), buf)
                    }));
                }
                State::Busy(ref mut rx) => {
                    let (op, mut buf) = ready!(Pin::new(rx).poll(cx))?;

                    match op {
                        Operation::Read(Ok(_)) => {
                            let unread = buf.buf.len() - buf.pos;
                            let dst_remaining = dst.buf.len() - dst.filled;
                            let n = cmp::min(unread, dst_remaining);
                            let bytes = &buf.buf[buf.pos..buf.pos + n];
                            let amt = bytes.len();
                            let end = dst.filled + amt;
                            unsafe {
                                dst.buf[dst.filled..end]
                                    .as_mut_ptr()
                                    .cast::<u8>()
                                    .copy_from_nonoverlapping(bytes.as_ptr(), amt);
                            }
                            if dst.initialized < end {
                                dst.initialized = end;
                            }
                            dst.filled = end;
                            buf.pos += n;
                            if buf.pos == buf.buf.len() {
                                buf.buf.truncate(0);
                                buf.pos = 0;
                            }
                            inner.state = State::Idle(Some(buf));
                            return Poll::Ready(Ok(()));
                        }
                        Operation::Read(Err(e)) => {
                            let unread = buf.buf.len() - buf.pos;
                            assert_eq!(unread, 0);
                            inner.state = State::Idle(Some(buf));
                            return Poll::Ready(Err(e));
                        }
                        Operation::Write(Ok(())) => {
                            let unread = buf.buf.len() - buf.pos;
                            assert_eq!(unread, 0);
                            inner.state = State::Idle(Some(buf));
                            continue;
                        }
                        Operation::Write(Err(e)) => {
                            assert!(inner.last_write_err.is_none());
                            inner.last_write_err = Some(e.kind());
                            inner.state = State::Idle(Some(buf));
                        }
                        Operation::Seek(result) => {
                            let unread = buf.buf.len() - buf.pos;
                            assert_eq!(unread, 0);
                            inner.state = State::Idle(Some(buf));
                            if let Ok(pos) = result {
                                inner.pos = pos;
                            }
                            continue;
                        }
                    }
                }
            }
        }
    }
}

